contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address nonOwner, address recipient) public {
        require(nonOwner != c.owner());
        require(address(c).balance == 0);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && address(c).balance == balBefore);
    }
    receive() external payable {}
}

