    function run(address recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        c.f{value: amount}();
        require(address(c).balance == amount);
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; }
        catch { reverted = true; }
        assert(!reverted && address(c).balance == 0);
    }
    receive() external payable {}
